"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["27972"],{95781(e){e.exports=JSON.parse('{"id":"FIN-1347","slug":"sources-and-uses","term":"Sources and Uses","also_known_as":[],"difficulty":"Advanced","definition":"Sources and uses is a summary table in a transaction, such as an acquisition or leveraged buyout, showing where the money to fund the deal comes from and how it will be spent.","explanation":["The table has two sides that must always balance. Sources list the funding: new debt, equity from investors, cash on the target\'s or acquirer\'s balance sheet, and sometimes seller financing or rollover equity from existing owners. Uses list the payments: the purchase price for the equity, repayment of the target\'s existing debt, transaction fees and financing fees.","For example, a buyer acquiring a company might need 600,000,000 in total: 500,000,000 for the shares, 80,000,000 to repay the target\'s existing debt and 20,000,000 for fees. It might fund this with 350,000,000 of new debt and 250,000,000 of equity.","The sources and uses table is one of the first things built in a transaction model. It determines how much debt and equity are needed, which drives the analysis of returns, leverage and earnings per share.","It also provides a clear summary for lenders, investors and boards of how the deal will be financed."],"note":"","total":1500,"prev":{"slug":"sortino-ratio","term":"Sortino Ratio"},"next":{"slug":"sovereign-default","term":"Sovereign Default"}}')}}]);